from pysat.solvers import Glucose3

def solve():
    n = 8
    d = 4
    g = 5

    solver = Glucose3()

    # Variables for edges
    def edge_var(u, v):
        if u > v: u, v = v, u
        return u * n + v + 1

    # Degree constraints
    from itertools import combinations
    for i in range(n):
        edges = [edge_var(i, j) for j in range(n) if i != j]
        # Exactly d edges
        # At least d
        for comb in combinations(edges, n - 1 - d + 1):
            solver.add_clause(list(comb))
        # At most d
        for comb in combinations(edges, d + 1):
            solver.add_clause([-x for x in comb])

    # Girth constraints
    # No cycles of length 3
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                solver.add_clause([-edge_var(i, j), -edge_var(j, k), -edge_var(i, k)])

    # No cycles of length 4
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # i-j-k-l-i
                    solver.add_clause([-edge_var(i, j), -edge_var(j, k), -edge_var(k, l), -edge_var(l, i)])
                    # i-j-l-k-i
                    solver.add_clause([-edge_var(i, j), -edge_var(j, l), -edge_var(l, k), -edge_var(k, i)])
                    # i-k-j-l-i
                    solver.add_clause([-edge_var(i, k), -edge_var(k, j), -edge_var(j, l), -edge_var(l, i)])

    print("SAT?", solver.solve())

solve()
